from toolz import partition_all

def make(delta):
    class L(list):
        def __len__(self):
            return super().__len__() + delta
    return L

# For every (actual_len, n, delta) where the OLD code produced corrupt output
# in the padding branch, the NEW code must raise LookupError.
# Corruption happens when reported_len%n != actual_len%n (and there's padding,
# i.e. actual_len % n != 0 and actual_len > 0).
failures = []
for actual in range(1, 12):
    for n in range(2, 8):
        if actual % n == 0:
            continue  # no padding branch; len not used, output is correct
        for delta in (-2, -1, 1, 2):
            cls = make(delta)
            try:
                res = list(partition_all(n, cls(list(range(actual)))))
            except LookupError:
                continue
            # Did not raise. Verify whether output is actually correct.
            expected = [tuple(range(i, min(i+n, actual))) for i in range(0, actual, n)]
            if res != expected:
                failures.append((actual, n, delta, res, expected))

if failures:
    print('UNRAISED CORRUPT CASES:')
    for f in failures:
        print(f)
else:
    print('All corrupt bad-len cases raise LookupError; no silent corruption.')

# Sanity: every bad-len case that does NOT raise must produce correct output.
# (covers exact-multiple actual lengths where len is unused)
for actual in range(1, 12):
    for n in range(2, 8):
        if actual % n != 0:
            continue
        for delta in (-2, -1, 1, 2):
            cls = make(delta)
            res = list(partition_all(n, cls(list(range(actual)))))
            expected = [tuple(range(i, min(i+n, actual))) for i in range(0, actual, n)]
            assert res == expected, (actual, n, delta, res, expected)
print('Exact-multiple bad-len cases still produce correct output (len unused).')
